// ends up withdrawn by a screen that sent the whole form back.
func (q *Queries) UpdateProductDetails(ctx context.Context, arg UpdateProductDetailsParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, updateProductDetails,
		arg.DgdaRegistration,
		arg.Notes,
		arg.SourceUrl,
		arg.GenericID,
		arg.ActorID,
		arg.ID,
		arg.FacilityID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const withdrawProduct = `-- name: WithdrawProduct :one
UPDATE core.medication_product
   SET is_active = false, withdrawn_at = now(),
       withdrawn_reason = $1, withdrawn_by = $2, updated_by = $2
 WHERE id = $3::uuid AND facility_id = $4::uuid AND is_active
RETURNING id
`

type WithdrawProductParams struct {
	Reason     *string
	ActorID    uuid.NullUUID
	ID         uuid.UUID
	FacilityID uuid.UUID
}

func (q *Queries) WithdrawProduct(ctx context.Context, arg WithdrawProductParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, withdrawProduct,
		arg.Reason,
		arg.ActorID,
		arg.ID,
		arg.FacilityID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
